public class Main {

    static boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        for (int i = 2; (long) i * i <= n; i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 17, 21, 97};
        for (int n : numbers) {
            System.out.println(n + (isPrime(n) ? " is Prime" : " is Not Prime"));
        }
    }
}

public class Main {

    // Recursive version: nth term (0-based)
    static int fib(int n) {
        return n <= 1 ? n : fib(n - 1) + fib(n - 2);
    }

    public static void main(String[] args) {
        int count = 10;
        long a = 0;
        long b = 1;

        StringBuilder series = new StringBuilder();
        for (int i = 0; i < count; i++) {
            series.append(a);
            if (i < count - 1) {
                series.append(" ");
            }
            long next = a + b;
            a = b;
            b = next;
        }

        System.out.println(series);
        System.out.println("10th term using recursion: " + fib(9));
    }
}

